#include <iostream>

int main() {
    int x = 42;
    int* p = &x;                     // p stores the address of x
    std::cout << "x = " << x << "\n";
    std::cout << "*p = " << *p << "\n";   // go to the address in p
    *p = 99;                         // change the box p points at
    std::cout << "x after *p = 99: " << x << "\n";
    std::cout << "p == &x: " << (p == &x ? "yes" : "no") << "\n";
    // The pointer is a variable with its own size (address width)
    std::cout << "sizeof(int*) = " << sizeof(int*)
              << ", sizeof(char*) = " << sizeof(char*) << "\n";
    int** pp = &p;                   // a pointer to the pointer
    **pp = 7;
    std::cout << "x via pointer to pointer: " << x << "\n";
    return 0;
}

#include <iostream>

int main() {
    int x = 1, y = 2;
    int& r = x;                      // r is another name for x
    r = y;                           // NOT re-seating: copies y's value into x
    std::cout << "after r = y: x=" << x << " y=" << y
              << " r aliases x: " << (&r == &x ? "yes" : "no") << "\n";

    int* p = &x;
    p = &y;                          // a pointer can be re-aimed
    *p = 50;
    std::cout << "after p = &y; *p = 50: x=" << x << " y=" << y << "\n";

    int* none = nullptr;             // a pointer can be null, a reference cannot
    std::cout << "none is null: " << (none == nullptr ? "yes" : "no") << "\n";
    return 0;
}

#include <iostream>

int main() {
    int a = 1, b = 2;

    const int* p1 = &a;          // pointer to const int
    p1 = &b;                     // OK: the pointer may move
    // *p1 = 5;                  // error: cannot write through it

    int* const p2 = &a;          // const pointer to int
    *p2 = 10;                    // OK: the int may change
    // p2 = &b;                  // error: the pointer is fixed

    const int* const p3 = &a;    // neither may change
    // *p3 = 1; p3 = &b;         // both errors

    int const* p4 = &a;          // identical type to const int*
    std::cout << "a=" << a << " b=" << b << "\n";
    std::cout << "*p1=" << *p1 << " *p2=" << *p2
              << " *p3=" << *p3 << " *p4=" << *p4 << "\n";
    std::cout << "p1 and p4 same type: "
              << (std::is_same_v<decltype(p1), decltype(p4)> ? "yes" : "no") << "\n";
    return 0;
}

#include <iostream>
#include <cstddef>
#include <type_traits>

void f(int)   { std::cout << "f(int) called\n"; }
void f(char*) { std::cout << "f(char*) called\n"; }

int main() {
    std::cout << "f(0):       "; f(0);          // 0 is an int literal
    std::cout << "f(nullptr): "; f(nullptr);    // nullptr is only a pointer
    auto x = nullptr;                           // deduces std::nullptr_t
    std::cout << "auto x = nullptr is nullptr_t: "
              << (std::is_same_v<decltype(x), std::nullptr_t> ? "yes" : "no") << "\n";
    char* p = nullptr;                          // converts to any pointer type
    std::cout << "p is null: " << (p == nullptr ? "yes" : "no") << "\n";
    return 0;
}

#include <iostream>
#include <cstddef>

int main() {
    int a[5] = {10, 20, 30, 40, 50};
    int* p = a;
    std::cout << "*(p+1) = " << *(p + 1) << ", p[1] = " << p[1]
              << ", 1[p] = " << 1[p] << "\n";           // p[i] is *(p+i)

    // p+1 moves sizeof(int) bytes; measure with a char* view
    std::ptrdiff_t bytes = (char*)(p + 1) - (char*)p;
    std::cout << "int* step = " << bytes << " bytes\n";
    char c[3] = {'a', 'b', 'c'};
    char* q = c;
    std::cout << "char* step = " << (char*)(q + 1) - (char*)q << " byte\n";

    int* end = a + 5;                // one-past-the-end: allowed, never dereference
    std::ptrdiff_t n = end - p;      // difference counts elements
    std::cout << "end - p = " << n << " elements\n";

    int i = 0;
    int v1 = *p++;                   // use then advance
    std::cout << "*p++ gave " << v1 << ", now *p = " << *p << "\n";
    (*p)++;                          // increments the pointed-at value
    std::cout << "(*p)++ -> a[1] = " << a[1] << ", i=" << i << "\n";
    return 0;
}

#include <iostream>
#include <iterator>

void takes(int arr[]) {                  // really: int* arr
    std::cout << "inside function sizeof(arr) = " << sizeof(arr) << "\n";
}

int main() {
    int a[10] = {0};
    std::cout << "sizeof(a) in main = " << sizeof(a) << "\n";   // 40: no decay
    takes(a);                                                   // decays to int*
    std::cout << "std::size(a) = " << std::size(a) << "\n";

    int* base = a + 1;                       // a + 1 moves one int
    int* whole = reinterpret_cast<int*>(&a + 1);   // &a + 1 moves the whole array
    std::cout << "a+1 step = " << (char*)base - (char*)a << " bytes\n";
    std::cout << "&a+1 step = " << (char*)whole - (char*)a << " bytes\n";

    int m[3][4] = {};
    int (*row)[4] = m;                       // 2-D array decays to pointer to row
    std::cout << "row step = " << (char*)(row + 1) - (char*)row << " bytes\n";
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v = {1, 2, 3};
    v.shrink_to_fit();                       // size == capacity (usually 3)
    int* before = v.data();                  // address of the old buffer
    std::size_t cap = v.capacity();
    while (v.size() < cap) v.push_back(0);   // fill without reallocation
    v.push_back(4);                          // forces a bigger buffer
    int* after = v.data();
    std::cout << "buffer moved: " << (before != after ? "yes" : "no")
              << " (old pointer is now dangling; we never dereference it)\n";

    // Safe fix 1: remember the index, not the pointer
    std::size_t idx = 1;
    std::cout << "by index v[1] = " << v[idx] << "\n";

    // Safe fix 2: reserve up front so the buffer never moves
    std::vector<int> w;
    w.reserve(100);
    w.push_back(7);
    int* first = &w[0];
    for (int i = 0; i < 50; ++i) w.push_back(i);
    std::cout << "reserved vector kept address: " << (first == &w[0] ? "yes" : "no")
              << ", *first = " << *first << "\n";
    return 0;
}

#include <iostream>
#include <memory>

int main() {
    // Null: deliberately empty, safe to test
    int* nul = nullptr;
    std::cout << "null pointer check: " << (nul ? "has object" : "empty") << "\n";

    // Wild: never initialized. Always initialize so it cannot be wild.
    int* safe = nullptr;                    // instead of: int* wild;
    std::cout << "initialized pointer is " << (safe ? "non-null" : "null") << "\n";

    // Dangling: object is gone. A raw pointer cannot tell you, a weak_ptr can.
    std::weak_ptr<int> observer;
    {
        auto owner = std::make_shared<int>(5);
        observer = owner;
        std::cout << "inside scope, expired = " << observer.expired() << "\n";
    }                                       // owner destroyed here
    std::cout << "after scope, expired = " << observer.expired() << "\n";
    if (auto sp = observer.lock()) std::cout << "still alive\n";
    else std::cout << "object is gone, no dereference attempted\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <string>
#include <utility>

int square(int n) { return n * n; }                         // cheap: by value
std::size_t len(const std::string& s) { return s.size(); }   // big, read-only
void addOne(int& x) { ++x; }                                 // mandatory in/out
void maybeSet(int* out) { if (out) *out = 42; }              // optional output
struct Owner {
    std::string name;
    void setName(std::string n) { name = std::move(n); }     // sink: copy then move
};
void consume(std::unique_ptr<int> p) { std::cout << "consumed " << *p << "\n"; }

int main() {
    int v = 5;
    std::cout << "square(5) = " << square(v) << "\n";
    std::cout << "len = " << len("hello world") << "\n";
    addOne(v);
    std::cout << "after addOne v = " << v << "\n";
    int out = 0;
    maybeSet(&out);
    maybeSet(nullptr);                                       // caller may skip it
    std::cout << "out = " << out << "\n";
    Owner o;
    o.setName("widget");
    std::cout << "name = " << o.name << "\n";
    consume(std::make_unique<int>(9));                       // ownership transferred
    return 0;
}

#include <iostream>

int main() {
    int a = 5;
    int* p = &a;

    const int* cp = p;                  // OK: int* -> const int*
    const int* const* ok = &p;          // OK: const added at every inner level
    std::cout << "**ok = " << **ok << "\n";

    // const int** bad = &p;            // ERROR: this would let us break const:
    //   const int ci = 1;
    //   *bad = &ci;                    // p now points at a const object
    //   *p = 99;                       // writes to a const int: undefined behaviour
    std::cout << "*cp = " << *cp << "\n";

    *p = 6;                             // legal: a really is not const
    std::cout << "a after *p = 6: " << a << ", **ok sees " << **ok << "\n";
    return 0;
}

#include <iostream>
#include <memory>

struct Point { int x; int y; };

int main() {
    Point pt{3, 4};
    Point* p = &pt;
    std::cout << "p->x = " << p->x << "\n";
    std::cout << "(*p).x = " << (*p).x << "\n";      // same thing
    // *p.x would parse as *(p.x): a pointer has no member x, so it won't compile

    auto up = std::make_unique<Point>(Point{7, 8});
    std::cout << "unique_ptr up->y = " << up->y << "\n";  // operator-> returns raw pointer

    int Point::* member = &Point::y;                 // pointer to member
    std::cout << "pt.*member = " << pt.*member << ", p->*member = " << p->*member << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <list>
#include <deque>
#include <cstdint>

template <class C>
bool stable(C& c) {
    c.push_back(1);
    const int* first = &*c.begin();          // address of the first element
    for (int i = 0; i < 1000; ++i) c.push_back(i);
    return first == &*c.begin();             // same address after growth?
}

int main() {
    std::vector<int> v;
    std::list<int> l;
    std::deque<int> d;
    std::cout << "vector address stable: " << (stable(v) ? "yes" : "no") << "\n";
    std::cout << "list   address stable: " << (stable(l) ? "yes" : "no") << "\n";
    std::cout << "deque  address stable: " << (stable(d) ? "yes" : "no") << "\n";

    std::vector<int> r;
    r.reserve(2000);                         // reserve first: buffer never moves
    std::cout << "vector with reserve stable: " << (stable(r) ? "yes" : "no") << "\n";
    return 0;
}
